CREATE OR REPLACE FUNCTION private.check_timezone()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
begin
  if not exists (select 1 from pg_catalog.pg_timezone_names where name = new.timezone) then
    raise check_violation using message = 'Invalid IANA timezone';
  end if;
  return new;
end;
$function$

CREATE OR REPLACE FUNCTION private.protect_asset_location()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
begin
  if (new.storage_bucket, new.storage_path, new.public_url, new.mime_type)
     is distinct from (old.storage_bucket, old.storage_path, old.public_url, old.mime_type) then
    raise check_violation using message = 'Asset locations and MIME types are immutable; create a replacement asset';
  end if;
  return new;
end;
$function$

CREATE OR REPLACE FUNCTION private.protect_markdown_asset_delete()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare token text;
begin
 token:='media:'||old.id;
 if exists(select 1 from public.posts where strpos(coalesce(content_markdown,''),token)>0)
 or exists(select 1 from public.projects where
   strpos(concat_ws(' ',problem,objective,solution,architecture,challenges,learnings,before_markdown,after_markdown),token)>0)
 or exists(select 1 from public.site_settings where
   strpos(concat_ws(' ',about_summary_markdown,about_profile_markdown,working_method_markdown),token)>0)
 then raise foreign_key_violation using message='Asset is still referenced by Markdown; unlink the editorial content first';
 end if;
 return old;
end; $function$

CREATE OR REPLACE FUNCTION private.refresh_media_visibility()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
begin
  update public.projects set featured_image_asset_id=featured_image_asset_id
    where new.id in (featured_image_asset_id,cover_image_asset_id,og_image_asset_id);
  update public.posts set featured_image_asset_id=featured_image_asset_id
    where new.id in (featured_image_asset_id,og_image_asset_id);
  update public.project_images set asset_id=asset_id where asset_id=new.id;
  update public.documents set asset_id=asset_id where asset_id=new.id;
  update public.site_settings set about_image_asset_id=about_image_asset_id;
  return null;
end;
$function$

CREATE OR REPLACE FUNCTION private.set_updated_at()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
begin
  new.updated_at := greatest(clock_timestamp(), old.updated_at + interval '1 microsecond');
  return new;
end;
$function$

CREATE OR REPLACE FUNCTION private.sync_asset_columns()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare
  source_id uuid;
  asset public.media_assets%rowtype;
  i integer;
  patch jsonb := '{}'::jsonb;
begin
  for i in 0..(tg_nargs / 2 - 1) loop
    source_id := (to_jsonb(new)->>tg_argv[i * 2])::uuid;
    if source_id is not null then
      select * into strict asset from public.media_assets where id = source_id for share;
      if tg_table_name = 'documents' then
        if asset.mime_type <> 'application/pdf' then
          raise check_violation using message = 'CV documents require a PDF asset';
        end if;
      elsif asset.mime_type not like 'image/%' then
        raise check_violation using message = 'Editorial image requires an image asset';
      end if;
    else
      asset := null;
    end if;
    if asset.visibility is distinct from 'public' then
      asset.public_url := null;
    end if;
    if tg_argv[i * 2 + 1] <> '' then
      patch := patch || jsonb_build_object(tg_argv[i * 2 + 1], asset.public_url);
    end if;
    if tg_table_name in ('documents','project_images') then
      patch := patch || jsonb_build_object('storage_path', asset.storage_path);
    end if;
  end loop;
  new := jsonb_populate_record(new, patch);
  return new;
end;
$function$

CREATE OR REPLACE FUNCTION private.sync_asset_references()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare
  i integer;
  source_id uuid;
begin
  for i in 1..(tg_nargs - 1) loop
    execute format('delete from public.media_references where %I = $1 and field = $2', tg_argv[0])
      using new.id, tg_argv[i];
    source_id := (to_jsonb(new)->>tg_argv[i])::uuid;
    if source_id is not null then
      execute format('insert into public.media_references (asset_id, %I, field) values ($1, $2, $3)', tg_argv[0])
        using source_id, new.id, tg_argv[i];
    end if;
  end loop;
  return new;
end;
$function$

CREATE OR REPLACE FUNCTION private.sync_markdown_media()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare field_name text; target uuid; token text; i integer;
begin
 for i in 1..tg_nargs-1 loop
  field_name:=tg_argv[i];
  execute format('delete from public.media_references where %I=$1 and field=$2',tg_argv[0]) using new.id,field_name;
  for token in select distinct m[1] from regexp_matches(coalesce(to_jsonb(new)->>field_name,''),'media:([[:alnum:]-]+)','g') m loop
   if token !~ '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' then raise check_violation using message='Markdown media references require canonical lowercase UUIDs'; end if;
   target:=token::uuid;
   execute format('insert into public.media_references(asset_id,%I,field) values($1,$2,$3) on conflict do nothing',tg_argv[0])
    using target,new.id,field_name;
  end loop;
 end loop;
 return new;
end; $function$

CREATE OR REPLACE FUNCTION private.validate_storage_object_identity()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare object_bucket text; object_path text;
begin
  if tg_op = 'UPDATE' then
    if new.storage_object_id is distinct from old.storage_object_id then
      raise check_violation using message = 'Storage identity is immutable; create a replacement asset';
    end if;
    return new;
  end if;
  -- Fail before inspecting Storage for a caller already excluded by owner RLS.
  if current_user = 'authenticated' and
    (not private.is_portfolio_admin() or new.created_by is distinct from auth.uid()) then
    raise insufficient_privilege using message = 'Active owner and matching asset author required';
  end if;
  -- Legacy SQL/editorial callers may omit the new column. Resolve an existing
  -- object, never generate a UUID pretending that an upload occurred.
  if new.storage_object_id is null then
    new.storage_object_id := (select o.id from storage.objects o
      where o.bucket_id = new.storage_bucket and o.name = new.storage_path);
  end if;
  -- API callers supply upload.data.id. Check its application location as well.
  -- This is a read, not a managed constraint/index or a Storage file operation.
  select o.bucket_id, o.name into object_bucket, object_path
  from storage.objects o where o.id = new.storage_object_id;
  if not found or object_bucket is distinct from new.storage_bucket
    or object_path is distinct from new.storage_path then
    raise foreign_key_violation using message = 'Storage object identity and location must match an accessible existing object';
  end if;
  return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.activate_cv(document_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
begin
 if not private.is_portfolio_admin() then raise insufficient_privilege using message='Owner required'; end if;
 perform pg_catalog.pg_advisory_xact_lock(816009);
 perform 1 from public.documents d join public.media_assets a on a.id=d.asset_id
  where d.id=document_id and d.type='cv' and a.mime_type='application/pdf' and a.visibility='public' for update of d;
 if not found then raise check_violation using message='An existing public PDF CV is required'; end if;
 update public.documents set active=false where type='cv' and active and id<>document_id;
 update public.documents set active=true where id=document_id;
end; $function$

CREATE OR REPLACE FUNCTION public.replace_media_asset(previous_id uuid, replacement_id uuid, expected_updated_at timestamp with time zone)
 RETURNS void
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare previous public.media_assets%rowtype; replacement public.media_assets%rowtype;
begin
 if not private.is_portfolio_admin() then raise insufficient_privilege using message='Owner required'; end if;
 if previous_id=replacement_id then raise check_violation using message='Replacement must have a new immutable location'; end if;
 -- Serialize media lifecycle transactions; content triggers acquire row locks through their FKs.
 perform pg_catalog.pg_advisory_xact_lock(816008);
 select * into strict previous from public.media_assets where id=previous_id for update;
 select * into strict replacement from public.media_assets where id=replacement_id for update;
 if expected_updated_at is null or previous.updated_at<>expected_updated_at then raise serialization_failure using message='Asset revision conflict'; end if;
 if (previous.mime_type='application/pdf')<>(replacement.mime_type='application/pdf')
  or (previous.visibility='public' and replacement.visibility<>'public') then
  raise check_violation using message='Replacement must preserve media kind and public availability';
 end if;
 update public.technologies set icon_asset_id=replacement_id where icon_asset_id=previous_id;
 update public.projects set
  featured_image_asset_id=case when featured_image_asset_id=previous_id then replacement_id else featured_image_asset_id end,
  cover_image_asset_id=case when cover_image_asset_id=previous_id then replacement_id else cover_image_asset_id end,
  og_image_asset_id=case when og_image_asset_id=previous_id then replacement_id else og_image_asset_id end,
  problem=replace(problem,'media:'||previous_id,'media:'||replacement_id),
  objective=replace(objective,'media:'||previous_id,'media:'||replacement_id),
  solution=replace(solution,'media:'||previous_id,'media:'||replacement_id),
  architecture=replace(architecture,'media:'||previous_id,'media:'||replacement_id),
  challenges=replace(challenges,'media:'||previous_id,'media:'||replacement_id),
  learnings=replace(learnings,'media:'||previous_id,'media:'||replacement_id),
  before_markdown=replace(before_markdown,'media:'||previous_id,'media:'||replacement_id),
  after_markdown=replace(after_markdown,'media:'||previous_id,'media:'||replacement_id)
 where id in(select project_id from public.media_references where asset_id=previous_id);
 update public.posts set
  featured_image_asset_id=case when featured_image_asset_id=previous_id then replacement_id else featured_image_asset_id end,
  og_image_asset_id=case when og_image_asset_id=previous_id then replacement_id else og_image_asset_id end,
  content_markdown=replace(content_markdown,'media:'||previous_id,'media:'||replacement_id)
 where id in(select post_id from public.media_references where asset_id=previous_id);
 update public.site_settings set
  about_image_asset_id=case when about_image_asset_id=previous_id then replacement_id else about_image_asset_id end,
  default_og_image_asset_id=case when default_og_image_asset_id=previous_id then replacement_id else default_og_image_asset_id end,
  about_summary_markdown=replace(about_summary_markdown,'media:'||previous_id,'media:'||replacement_id),
  about_profile_markdown=replace(about_profile_markdown,'media:'||previous_id,'media:'||replacement_id),
  working_method_markdown=replace(working_method_markdown,'media:'||previous_id,'media:'||replacement_id)
 where id in(select settings_id from public.media_references where asset_id=previous_id);
 update public.project_images set asset_id=replacement_id where asset_id=previous_id;
 update public.documents set asset_id=replacement_id where asset_id=previous_id;
 -- Explicitly registered uses without an editorial FK remain conservatively protected.
 if exists(select 1 from public.media_references where asset_id=previous_id) then
  raise check_violation using message='Unresolved media references; unlink explicitly';
 end if;
 -- Retain the previous asset and bytes; removal is a separate deliberate operation.
end; $function$

CREATE OR REPLACE FUNCTION public.rls_auto_enable()
 RETURNS event_trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
DECLARE
  cmd record;
BEGIN
  FOR cmd IN
    SELECT *
    FROM pg_event_trigger_ddl_commands()
    WHERE command_tag IN ('CREATE TABLE', 'CREATE TABLE AS', 'SELECT INTO')
      AND object_type IN ('table','partitioned table')
  LOOP
     IF cmd.schema_name IS NOT NULL AND cmd.schema_name IN ('public') AND cmd.schema_name NOT IN ('pg_catalog','information_schema') AND cmd.schema_name NOT LIKE 'pg_toast%' AND cmd.schema_name NOT LIKE 'pg_temp%' THEN
      BEGIN
        EXECUTE format('alter table if exists %s enable row level security', cmd.object_identity);
        RAISE LOG 'rls_auto_enable: enabled RLS on %', cmd.object_identity;
      EXCEPTION
        WHEN OTHERS THEN
          RAISE LOG 'rls_auto_enable: failed to enable RLS on %', cmd.object_identity;
      END;
     ELSE
        RAISE LOG 'rls_auto_enable: skip % (either system schema or not in enforced list: %.)', cmd.object_identity, cmd.schema_name;
     END IF;
  END LOOP;
END;
$function$
